def _parse_args_for_command(args_list: List[str], command_type: str) -> Any:
    """
    Parse only the arguments relevant for the given command type.

    Args:
        args_list: Raw CLI-style argument list (not including the program name)
        command_type: 'build' or 'search'

    Returns:
        argparse.Namespace for that command
    """
    parser = _build_base_parser()

    # The LEANN CLI expects the command name as the first positional argument.
    # If the caller provides args without it, inject it.
    if not args_list or args_list[0] != command_type:
        parse_list = [command_type] + list(args_list)
    else:
        parse_list = list(args_list)

    parsed = parser.parse_args(parse_list)

    # Sanity check: ensure we parsed the expected command
    if getattr(parsed, "command", None) != command_type:
        raise ValueError(
            f"Parsed command '{getattr(parsed, 'command', None)}' "
            f"does not match expected '{command_type}'. "
            f"Raw args: {args_list!r}"
        )

    return parsed


