    into a structured configuration dictionary that can be used
    programmatically.

    Args:
        args_list: List of command line arguments (excluding the program name).
            They may include or omit the command name itself; if omitted, the
            provided `command_type` is injected.
        command_type: Type of command ('build' or 'search').

    Returns:
        Dictionary containing API configuration extracted from CLI arguments.

    Raises:
        ValueError: If an unsupported command_type is provided or the parsed
            command does not match the expected type.
    """
    if command_type not in {"build", "search"}:
        raise ValueError(f"Unsupported command_type: {command_type!r}")

    ns = _parse_args_for_command(args_list, command_type)

    if command_type == "build":
        return _namespace_to_config_build(ns)
    else:  # command_type == "search"
        return _namespace_to_config_search(ns)
