from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, List


def _resolve_meta_path(index_path: str) -> Path:
    """
    Given a path to an index file, resolve the corresponding LEANN metadata file.

    LEANN uses "<base>.leann" for the index and "<base>.leann.meta.json"
    for the metadata, in the same directory.
    """
    idx = Path(index_path)

    # Basic existence check for the index file itself is not required by the spec,
    # but we still construct the meta path purely from the given index_path.
    if idx.suffix != ".leann":
        # Support callers that pass the base without ".leann"
        base = idx
    else:
        base = idx.with_suffix("")  # strip ".leann"

    meta_path = base.with_suffix(".leann.meta.json")
    if not meta_path.exists():
        raise FileNotFoundError(f"Index metadata file not found: {meta_path}")
    return meta_path


def _iter_metadata_records(meta_path: Path):
    """
    Yield metadata dicts for each passage from a LEANN meta file.

    Expected format (based on typical LEANN usage):
    {
      "documents": [
        {"metadata": {...}, ...},
        ...
      ]
    }
    or, in some variants, a top-level list.
    """
    with meta_path.open("r", encoding="utf-8") as f:
        data = json.load(f)

    # Try common layouts
    if isinstance(data, dict) and "documents" in data and isinstance(data["documents"], list):
        docs = data["documents"]
    elif isinstance(data, list):
        docs = data
    else:
        # Fallback: treat any dict entries that look like documents
        docs = []
        if isinstance(data, dict):
            for v in data.values():
                if isinstance(v, list):
                    docs.extend(v)

    for doc in docs:
        meta = doc.get("metadata") if isinstance(doc, dict) else None
        if isinstance(meta, dict):
            yield meta
        else:
            # If no explicit metadata field, treat entire doc as metadata if dict
            if isinstance(doc, dict):
                yield {k: v for k, v in doc.items() if k != "text"}


def get_index_statistics(index_path: str) -> Dict[str, Any]:
    """Get comprehensive statistics about a index.

Args:
    index_path: Path to the index file

Returns:
    Dictionary containing:
    {
        "total_passages": total number of passages,
        "metadata_fields": list of unique metadata field names,
        "field_value_counts": dictionary of field value counts
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""
    meta_path = _resolve_meta_path(index_path)

    total_passages = 0
    field_names: set[str] = set()
    field_value_counts: Dict[str, Dict[str, int]] = {}

    for metadata in _iter_metadata_records(meta_path):
        total_passages += 1
        for key, value in metadata.items():
            field_names.add(key)
            # Represent value as string for counting (JSON-serializable / readable)
            val_str = json.dumps(value, sort_keys=True, ensure_ascii=False)
            field_value_counts.setdefault(key, {})
            field_value_counts[key][val_str] = field_value_counts[key].get(val_str, 0) + 1

    return {
        "total_passages": total_passages,
        "metadata_fields": sorted(field_names),
        "field_value_counts": field_value_counts,
    }


def analyze_index_coverage(index_path: str, required_fields: List[str]) -> Dict[str, Any]:
    """Analyze how well an index covers required metadata fields.

Args:
    index_path: Path to the index file
    required_fields: List of metadata field names that should be present

Returns:
    Dictionary containing:
    {
        "coverage_percentage": percentage of passages that have all required fields,
        "field_coverage": dictionary mapping field name to coverage percentage,
        "missing_fields": list of required fields not found in any passage
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""
    meta_path = _resolve_meta_path(index_path)

    total_passages = 0
    # Count for each required field: how many passages contain it (non-null)
    field_counts: Dict[str, int] = {f: 0 for f in required_fields}
    fully_covered_passages = 0

    for metadata in _iter_metadata_records(meta_path):
        total_passages += 1
        has_all = True
        for field in required_fields:
            value = metadata.get(field, None)
            if value is not None:
                field_counts[field] += 1
            else:
                has_all = False
        if has_all:
            fully_covered_passages += 1

    if total_passages == 0:
        coverage_percentage = 0.0
        field_coverage = {f: 0.0 for f in required_fields}
    else:
        coverage_percentage = (fully_covered_passages / total_passages) * 100.0
        field_coverage = {
            f: (field_counts[f] / total_passages) * 100.0 for f in required_fields
        }

    missing_fields = [f for f in required_fields if field_counts.get(f, 0) == 0]

    return {
        "coverage_percentage": coverage_percentage,
        "field_coverage": field_coverage,
        "missing_fields": missing_fields,
    }
